from pathlib import Path
import pandas as pd
import streamlit as st

st.set_page_config(page_title="Museum visitors", layout="wide")


@st.cache_data
def load_data():
    return pd.read_csv(Path(__file__).with_name("visitors.csv"))


st.title("Museum visitors")
try:
    data = load_data()
except FileNotFoundError:
    st.error("Put visitors.csv next to app.py.")
    st.stop()
st.caption(f"{len(data)} days, {data['visitors'].sum():,} visitors")

