from pathlib import Path
import pandas as pd
import streamlit as st

st.set_page_config(page_title="Reading room", layout="wide")


@st.cache_data
def load_data():
    return pd.read_csv(Path(__file__).with_name("seats.csv"))


st.title("Reading room seats")

try:
    data = load_data()
except FileNotFoundError:
    st.error("Put seats.csv next to app.py.")
    st.stop()
if len(data) == 0:
    st.error("seats.csv has no rows.")
    st.stop()
st.caption(f"Data: {len(data)} days, {data['seats'].sum():,} seats")
